import re
def grep(r, pats, w=300):
    for x in r:
        if x.get('type')!='web_search_result': continue
        c=x.get('content','')
        for p in pats:
            for m in re.finditer(p,c,flags=re.I):
                print(f"[{x['url'][:70]}] ...{c[max(0,m.start()-w):m.end()+w]}...".replace("\n"," "))
                break
